public int findKthLargest(int[] nums, int k) {
    PriorityQueue<Integer> minHeap = new PriorityQueue<>();   // natural order = min-heap
    for (int x : nums) {
        minHeap.offer(x);
        if (minHeap.size() > k) {
            minHeap.poll();      // drop the smallest — it can't be in the k largest
        }
    }
    return minHeap.peek();       // top of a size-k min-heap is the kth largest
}

