import heapq

def find_kth_largest(self, nums: list[int], k: int) -> int:
    min_heap: list[int] = []
    for x in nums:
        heapq.heappush(min_heap, x)
        if len(min_heap) > k:
            heapq.heappop(min_heap)   # pops the smallest → drop it
    return min_heap[0]                # top is the kth largest

