public int findKthLargest(int[] nums, int k) {
    int lo = 0, hi = nums.length - 1, target = nums.length - k;
    Random rnd = new Random();
    while (lo <= hi) {
        int p = partition(nums, lo, hi, rnd);
        if (p == target) return nums[p];
        if (p < target) lo = p + 1;   // answer is to the right
        else hi = p - 1;             // answer is to the left
    }
    return -1;   // unreachable for valid k
}

private int partition(int[] nums, int lo, int hi, Random rnd) {
    int r = lo + rnd.nextInt(hi - lo + 1);
    swap(nums, r, hi);               // random pivot → guard the O(n^2) worst case
    int pivot = nums[hi], i = lo;
    for (int j = lo; j < hi; j++) {
        if (nums[j] < pivot) {       // Lomuto: smaller elements go left of i
            swap(nums, i, j);
            i++;
        }
    }
    swap(nums, i, hi);               // place pivot in its final sorted slot
    return i;
}

private void swap(int[] a, int x, int y) {
    int t = a[x]; a[x] = a[y]; a[y] = t;
}

